<main id="main" class="admin-page"><h1>Mensagens</h1><?php require INCLUDES_PATH.'/admin_nav.php' ?><?php if(!$rows): ?><div class="empty-state"><h2>O rádio está em silêncio.</h2><p>As mensagens enviadas pelo contato aparecerão aqui.</p></div><?php endif ?><div class="message-list"><?php foreach($rows as $row): ?><article class="message-row"><div><span class="status-badge"><?= e($row['status']) ?></span><h2><?= e($row['subject']?:'Sem assunto') ?></h2><p class="muted"><?= e($row['name']) ?> · <?= e($row['email']) ?> · <?= e($row['created_at']) ?></p><p class="message-text"><?= e($row['message']) ?></p></div><form class="stack-form" method="post" action="<?= e(url('admin_status')) ?>"><?php csrf_field() ?><input type="hidden" name="id" value="<?= e($row['id']) ?>"><label for="status-<?= e($row['id']) ?>">Situação<select name="status" id="status-<?= e($row['id']) ?>"><?php foreach(Message::STATUSES as $status): ?><option <?= $status===$row['status']?'selected':'' ?>><?= e($status) ?></option><?php endforeach ?></select></label><button class="button outline">Atualizar</button></form></article><?php endforeach ?></div><?php require INCLUDES_PATH.'/pagination.php' ?></main>
